  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Prednisolone, the closest corticosteroid analogue, had an absolute oral bioavailability of 0.92 from tablets versus IV prednisolone, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Methylprednisolone, a close structural analogue, showed 82.4% absolute oral bioavailability versus IV, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone, a related corticosteroid, had an absolute oral bioavailability of 95.9% after oral versus IV administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Dexamethasone, another related corticosteroid, had a mean absolute oral bioavailability of 60.7% (range 33.7-89.2%), still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a chlorinated corticosteroid closely related to prednisolone, methylprednisolone, and hydrocortisone, all of which show absolute oral bioavailability well above 20% (typically 60-100%). No affirmative evidence supports low bioavailability, so the prediction is high.",
  "evidence_gaps": [
    "No direct cloprednol absolute bioavailability measurement is present in the evidence set; prediction relies on close corticosteroid analogues.",
    "The specific effect of the 6-chloro and additional 6,7-double bond on first-pass metabolism is not directly evidenced, though the overall corticosteroid pattern strongly supports high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

